-- Piłka ręczna, judo, lacrosse, pięciobój nowoczesny, pływanie na otwartym akwenie, gimnastyka artystyczna
-- i nowy kafel: skoki na trampolinie – tablice kwot LA28 i kalendarze. Można uruchomić ponownie.
-- Źródła: systemy kwalifikacji IHF, IJF, World Lacrosse, UIPM, World Aquatics, FIG dla LA28;
-- wyniki MŚ w gimnastyce artystycznej 2026 (Frankfurt).

insert into public.dyscypliny (slug, nazwa, plakietka, sledzona, opis_kafla, kolejnosc)
select 'gimnastyka-trampoliny', 'Skoki na trampolinie', null, false, null, kolejnosc from public.dyscypliny where slug = 'gimnastyka-artystyczna'
on conflict (slug) do nothing;

update public.dyscypliny set opis_kafla = v.opis from (values
  ('pilka-reczna', 'Kobiety i mężczyźni · 12 drużyn · ME kobiet 2026 współorganizuje Polska'),
  ('judo', '7 kategorii kobiet i 7 mężczyzn + drużyna mieszana · ranking IJF'),
  ('lacrosse', 'Sixes · kobiety i mężczyźni · 6 drużyn'),
  ('piecioboj-nowoczesny', 'Kobiety i mężczyźni · 32 miejsca · ME 2027 to 8 miejsc'),
  ('plywanie-otwarte-akweny', '10 km · kobiety i mężczyźni · 22 miejsca'),
  ('gimnastyka-artystyczna', 'Indywidualnie i układy · MŚ 2027 w Baku'),
  ('gimnastyka-trampoliny', 'Kobiety i mężczyźni · 16 miejsc · MŚ 2027')
) as v(slug, opis) where dyscypliny.slug = v.slug;

