  ('gimnastyka-artystyczna', 'indywidualnie', 'Gimnastyka artystyczna – indywidualnie', 'K', 24::smallint, null, 'Wielobój indywidualny, 24 zawodniczki, maks. 2 z kraju.', '{"typ": "kwoty", "etykieta": "Indywidualnie"}'),
